227			}
228		}
229		// 字段顺序：前四个字段在 explanation 之前。
230		s := string(out)
231		ei := strings.Index(s, `"explanation"`)
232		for _, k := range []string{`"key"`, `"value"`, `"reason"`, `"ruleId"`} {
233			if p := strings.Index(s, k); p < 0 || p > ei {
234				t.Fatalf("field %s must appear before explanation in %s", k, s)
235			}
236		}
237	
238		// 缺失属性渲染为 actualValue:null、missing:true；显式空串为 actualValue:""。
239		disabled := explainFlag(t, "off").EvaluateExplain(mustParseContext(t, `{}`))
240		dout, _ := MarshalExplain(disabled)
241		if !strings.Contains(string(dout), `"reason":"disabled"`) ||
242			!strings.Contains(string(dout), `"rules":[]`) {
243			t.Fatalf("disabled explain output wrong: %s", dout)
244		}
245	}
246	
247	func explainedIDs(r ExplainedResult) []string {
248		ids := make([]string, 0, len(r.Explanation.Rules))
249		for _, rr := range r.Explanation.Rules {
250			ids = append(ids, rr.RuleID)
251		}
252		return ids
253	}
